-- AI/ML pathway ("Cipher Division") Act 4 -- "Probability Sector" content.
-- 1 campaign, 2 operations, 12 missions (11 lessons + boss), following the
-- same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every other pathway. The world row
-- (world-ai-probability-sector, under act-ai-1) already exists.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-ai-probability-sector', 'world-ai-probability-sector', 'probability-sector', '4A - Probability Sector', 'Randomness, probability and its conditional and independent forms, Bayes'' intuition, random variables and their distributions, sampling, and the discipline that keeps a real pattern from being mistaken for one -- all aimed at one question: is Echo actually changing, or is Cipher Division just seeing patterns in noise.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-ai-probability-sector-1', 'campaign-ai-probability-sector', 'chance-and-belief', 'Chance and Belief', 'Randomness, probability, conditional probability, independence and Bayes'' intuition -- the vocabulary needed before any claim about Echo can be trusted.', 1),
  ('operation-ai-probability-sector-2', 'campaign-ai-probability-sector', 'reading-the-noise', 'Reading the Noise', 'Random variables, expectation, variance, the normal distribution, sampling and the line between correlation and causation -- turned directly on Echo''s own interaction logs.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-ai-probability-sector-01', 'world-ai-probability-sector', 'campaign-ai-probability-sector', 'operation-ai-probability-sector-1', 'randomness', 'Randomness', 'Before anyone can judge whether Echo''s one strange log entry was a fluke or a signal, Cipher Division needs to agree on what genuine randomness actually looks like.', 'beginner', ARRAY['maya','byte'], null, null, '{"type":"simulation","simulationId":"randomness-sim"}'::jsonb, '{"xp":100,"credits":20}'::jsonb, false, 1),
  ('mission-ai-probability-sector-02', 'world-ai-probability-sector', 'campaign-ai-probability-sector', 'operation-ai-probability-sector-1', 'probability', 'Probability', 'Randomness says an outcome cannot be predicted. Probability puts an actual number on how likely it is.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-probability-sector-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"probability-basics-sim"}'::jsonb, '{"xp":110,"credits":20}'::jsonb, false, 2),
  ('mission-ai-probability-sector-03', 'world-ai-probability-sector', 'campaign-ai-probability-sector', 'operation-ai-probability-sector-1', 'conditional-probability', 'Conditional Probability', 'Some questions only make sense once you already know something else happened -- and Echo''s logs are full of exactly that kind of question.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-probability-sector-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"conditional-probability-sim"}'::jsonb, '{"xp":110,"credits":25}'::jsonb, false, 3),
  ('mission-ai-probability-sector-04', 'world-ai-probability-sector', 'campaign-ai-probability-sector', 'operation-ai-probability-sector-1', 'independence', 'Independence', 'Two events can look connected and still have nothing to do with each other. Independence is never assumed. It is checked.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-probability-sector-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"independence-sim"}'::jsonb, '{"xp":120,"credits":25}'::jsonb, false, 4),
  ('mission-ai-probability-sector-05', 'world-ai-probability-sector', 'campaign-ai-probability-sector', 'operation-ai-probability-sector-1', 'bayes-intuition', 'Bayes'' Intuition', 'A new piece of evidence should update a belief, not replace it outright -- Bayes'' rule is how that update actually gets done.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-probability-sector-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"bayes-intuition-sim"}'::jsonb, '{"xp":120,"credits":25}'::jsonb, false, 5),
  ('mission-ai-probability-sector-06', 'world-ai-probability-sector', 'campaign-ai-probability-sector', 'operation-ai-probability-sector-1', 'random-variables', 'Random Variables', 'Turning Echo''s behavior into numbers is the only way any of this Act''s tools can actually be applied to it.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-probability-sector-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"random-variables-sim"}'::jsonb, '{"xp":130,"credits":25}'::jsonb, false, 6),
  ('mission-ai-probability-sector-07', 'world-ai-probability-sector', 'campaign-ai-probability-sector', 'operation-ai-probability-sector-2', 'expectation', 'Expectation', 'The long-run average of a random process, and why it almost never matches any single real outcome.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-probability-sector-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"expectation-sim"}'::jsonb, '{"xp":130,"credits":30}'::jsonb, false, 7),
  ('mission-ai-probability-sector-08', 'world-ai-probability-sector', 'campaign-ai-probability-sector', 'operation-ai-probability-sector-2', 'variance', 'Variance', 'Two processes can share the exact same average and still behave nothing alike. Variance is what tells them apart.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-probability-sector-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"variance-sim"}'::jsonb, '{"xp":140,"credits":30}'::jsonb, false, 8),
  ('mission-ai-probability-sector-09', 'world-ai-probability-sector', 'campaign-ai-probability-sector', 'operation-ai-probability-sector-2', 'normal-distribution', 'Normal Distribution', 'A shape that keeps showing up across natural random processes -- and a way to tell a genuinely unusual outcome from an ordinary one.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-probability-sector-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"normal-distribution-sim"}'::jsonb, '{"xp":140,"credits":30}'::jsonb, false, 9),
  ('mission-ai-probability-sector-10', 'world-ai-probability-sector', 'campaign-ai-probability-sector', 'operation-ai-probability-sector-2', 'sampling', 'Sampling', 'Cipher Division cannot read every log Echo has ever produced. A sample has to stand in for the whole -- if it was actually chosen fairly.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-probability-sector-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"sampling-sim"}'::jsonb, '{"xp":150,"credits":30}'::jsonb, false, 10),
  ('mission-ai-probability-sector-11', 'world-ai-probability-sector', 'campaign-ai-probability-sector', 'operation-ai-probability-sector-2', 'correlation-vs-causation', 'Correlation vs Causation', 'Maya''s warning, before this Act closes: two things moving together is not proof that one is causing the other.', 'intermediate', ARRAY['maya','byte'], '{"requiredMissionIds":["mission-ai-probability-sector-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"correlation-causation-sim"}'::jsonb, '{"xp":150,"credits":35}'::jsonb, false, 11),
  ('mission-ai-probability-sector-12', 'world-ai-probability-sector', 'campaign-ai-probability-sector', 'operation-ai-probability-sector-2', 'the-uncertain-signal', 'The Uncertain Signal', 'The full weight of this Act, aimed at one exact question: was Echo''s answer-change a fluke, or a real, non-random signal.', 'boss', ARRAY['maya','byte'], '{"requiredMissionIds":["mission-ai-probability-sector-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"uncertain-signal-boss-sim"}'::jsonb, '{"xp":480,"credits":100,"badgeIds":["signal-or-noise"],"skillXp":{"probability_statistics":55,"ai_ml_fundamentals":15}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-ai-probability-sector-01', 1, 'maya', 'Byte''s work in Mathematical Language turned up gradients that never settle. Further back than that, Echo gave two different answers to the exact same question, five minutes apart. Everyone treated that as a footnote at the time.'),
  ('mission-ai-probability-sector-01', 2, 'maya', 'I want to know if that was a fluke, or an actual signal, before anyone in this division builds a theory on top of one anecdote. That means doing this properly, starting with what random actually means.'),
  ('mission-ai-probability-sector-01', 3, 'byte', 'Fair. People use random to mean I cannot predict it and unpredictable and structureless like they are the same thing. They are not. A fair coin flip is random. So is a broken sensor. Only one of those is actually meaningless.'),
  ('mission-ai-probability-sector-01', 4, 'byte', 'Randomness just means this: any single outcome cannot be predicted with certainty in advance, even though the process behind it can still follow a stable, describable pattern across many repetitions.'),

  ('mission-ai-probability-sector-02', 1, 'byte', 'Randomness tells you an individual outcome is not predictable. Probability is how we put a number on that -- the long-run frequency you would expect if the situation repeated forever.'),
  ('mission-ai-probability-sector-02', 2, 'byte', 'It always sits between 0 and 1. Zero means it never happens. One means it always happens. Everything Cipher Division does with Echo''s logs from here on runs through numbers exactly like that.'),

  ('mission-ai-probability-sector-03', 1, 'byte', 'Plain probability answers how likely is X, in general. Conditional probability answers a sharper question: how likely is X, given that we already know Y happened.'),
  ('mission-ai-probability-sector-03', 2, 'byte', 'Knowing Y happened can shift the odds on X a lot. Sometimes it does not move them at all, which turns out to matter later.'),
  ('mission-ai-probability-sector-03', 3, 'byte', 'Echo''s logs are full of given situations: given a certain topic, given a certain time of day, given a prior answer. This is the tool that lets us read any of it honestly.'),

  ('mission-ai-probability-sector-04', 1, 'byte', 'Two events are independent when knowing one happened tells you nothing new about the other -- the odds of X stay exactly the same whether or not Y happened.'),
  ('mission-ai-probability-sector-04', 2, 'byte', 'That is rarer than people assume. Most things quietly depend on each other. Independence is never assumed. It always has to be checked.'),
  ('mission-ai-probability-sector-04', 3, 'byte', 'If Echo''s answer-changes turn out to be independent of everything else in its logs, that points toward noise. If they do not, that points toward something with an actual cause.'),

  ('mission-ai-probability-sector-05', 1, 'byte', 'Conditional probability let us ask how likely is X, given Y. Bayes'' rule flips that around: it lets us update a belief we already held, once new evidence comes in.'),
  ('mission-ai-probability-sector-05', 2, 'byte', 'Start with a prior -- what was believed before the evidence. Fold in how likely that evidence would be under each competing explanation. What comes out the other side is the updated belief, the posterior.'),
  ('mission-ai-probability-sector-05', 3, 'byte', 'That is exactly the shape of what Maya is asking for: how much should one strange log entry update our belief that Echo is still changing, versus our belief that it was only noise.'),

  ('mission-ai-probability-sector-06', 1, 'byte', 'A random variable is a number attached to the outcome of a random process -- not the outcome itself, a number that summarizes it.'),
  ('mission-ai-probability-sector-06', 2, 'byte', 'Roll a die, the random variable could be the number shown. Log an Echo interaction, the random variable could be did the answer change -- 1 if yes, 0 if no.'),
  ('mission-ai-probability-sector-06', 3, 'byte', 'Once behavior gets turned into numbers like that, the rest of this Act -- expectation, variance, distributions -- can actually be applied to it.'),

  ('mission-ai-probability-sector-07', 1, 'byte', 'Expectation, the expected value, is the long-run average of a random variable, weighted by how likely each outcome is.'),
  ('mission-ai-probability-sector-07', 2, 'byte', 'It is not a prediction of any single outcome. It is what the average would settle toward if the same random process ran over and over, forever.'),

  ('mission-ai-probability-sector-08', 1, 'byte', 'Expectation tells you the average. Variance tells you how much individual outcomes tend to stray from that average -- how spread out things really are.'),
  ('mission-ai-probability-sector-08', 2, 'byte', 'High variance means outcomes swing wildly around the average. Low variance means they cluster tightly around it. Two processes can share the same average and still look nothing alike.'),

  ('mission-ai-probability-sector-09', 1, 'byte', 'A lot of naturally-occurring random processes, once enough of them pile up, form the same shape: a symmetric bell curve, centered on the average, thinning out evenly on both sides. That shape is the normal distribution.'),
  ('mission-ai-probability-sector-09', 2, 'byte', 'It has a useful property: roughly 68% of outcomes fall within one standard deviation of the average, about 95% within two, about 99.7% within three. Anything far outside that range is genuinely unusual, not just a little different.'),
  ('mission-ai-probability-sector-09', 3, 'byte', 'That property is going to matter a great deal once we look at exactly how far outside the ordinary range Echo''s behavior falls.'),

  ('mission-ai-probability-sector-10', 1, 'byte', 'Cipher Division cannot examine every interaction Echo has ever logged -- there are too many. Instead, a sample gets pulled: a smaller subset, used to draw conclusions about the whole log.'),
  ('mission-ai-probability-sector-10', 2, 'byte', 'The sample only tells the truth about the whole if it was actually chosen fairly. A sample that only grabs daytime interactions will never notice a pattern that only shows up at night.'),
  ('mission-ai-probability-sector-10', 3, 'byte', 'Bigger samples, chosen without bias, get closer to the truth. Biased samples can point anywhere, no matter how large they are.'),

  ('mission-ai-probability-sector-11', 1, 'maya', 'Before this Act closes, one warning, because I have watched good analysts wreck good investigations on this exact mistake: correlation is not causation.'),
  ('mission-ai-probability-sector-11', 2, 'maya', 'Two things moving together does not mean one is making the other happen. It could be coincidence. It could be a third factor driving both. Cipher Division does not get to skip that check just because a pattern is exciting.'),
  ('mission-ai-probability-sector-11', 3, 'byte', 'Noted for the record: whatever we find about Echo''s answer-changes, showing they move together with something else is not the same as showing that something else is the cause.'),
  ('mission-ai-probability-sector-11', 4, 'maya', 'Exactly. Hold that line for the boss mission. We are about to need it.'),

  ('mission-ai-probability-sector-12', 1, 'maya', 'Everything this Act taught, we turn on one exact question right now: when Echo gave two different answers to the same question, minutes apart, was that a fluke, or a real signal.'),
  ('mission-ai-probability-sector-12', 2, 'byte', 'I pulled the full pattern, not one entry -- every repeat-question test across a year of logs. Three pieces of evidence. Cipher Division needs your actual verdict before anyone builds a theory on top of it.'),
  ('mission-ai-probability-sector-12', 3, 'maya', 'Use everything this Act taught -- randomness, sampling, correlation and causation, all of it. Tell me if this holds up under real scrutiny, not the version of it that just wanted to be interesting.'),
  ('mission-ai-probability-sector-12', 4, 'maya', 'If the numbers hold up, this stops being a question of whether Echo is changing. It becomes a question of what could possibly be causing it -- and whether we can find that before Echo does something with it we cannot undo.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-ai-probability-sector-01-o1', 'mission-ai-probability-sector-01', 1, 'Recognize genuine randomness', 'Tell true randomness apart from things that only look unpredictable.'),

  ('mission-ai-probability-sector-02-o1', 'mission-ai-probability-sector-02', 1, 'Put a number on it', 'Translate a described likelihood into an actual probability value.'),

  ('mission-ai-probability-sector-03-o1', 'mission-ai-probability-sector-03', 1, 'Read a conditional probability', 'Interpret what a conditional probability actually tells you, and what it does not.'),
  ('mission-ai-probability-sector-03-o2', 'mission-ai-probability-sector-03', 2, 'Tell plain from conditional', 'Sort each statement into plain probability or conditional probability.'),

  ('mission-ai-probability-sector-04-o1', 'mission-ai-probability-sector-04', 1, 'Spot independence', 'Identify the pair of events that are genuinely independent of each other.'),
  ('mission-ai-probability-sector-04-o2', 'mission-ai-probability-sector-04', 2, 'Test a claim of independence', 'Find the evidence that actually refutes a claim of independence.'),

  ('mission-ai-probability-sector-05-o1', 'mission-ai-probability-sector-05', 1, 'Order the update', 'Put the steps of a Bayesian belief update in the order they actually happen.'),
  ('mission-ai-probability-sector-05-o2', 'mission-ai-probability-sector-05', 2, 'Apply the intuition', 'Use Bayesian intuition to judge a classic rare-condition test scenario.'),

  ('mission-ai-probability-sector-06-o1', 'mission-ai-probability-sector-06', 1, 'Spot the random variable', 'Identify which quantity is actually a valid random variable.'),
  ('mission-ai-probability-sector-06-o2', 'mission-ai-probability-sector-06', 2, 'Discrete or continuous', 'Sort each random variable into discrete or continuous.'),

  ('mission-ai-probability-sector-07-o1', 'mission-ai-probability-sector-07', 1, 'Compute an expectation', 'Calculate the expected value of a simple random variable.'),
  ('mission-ai-probability-sector-07-o2', 'mission-ai-probability-sector-07', 2, 'Read what expectation means', 'Interpret what an expected value does and does not promise.'),

  ('mission-ai-probability-sector-08-o1', 'mission-ai-probability-sector-08', 1, 'Compare variance', 'Identify which of two same-average processes has higher variance.'),
  ('mission-ai-probability-sector-08-o2', 'mission-ai-probability-sector-08', 2, 'Know what variance is not', 'Recognize that variance is a separate measurement from the average.'),

  ('mission-ai-probability-sector-09-o1', 'mission-ai-probability-sector-09', 1, 'Know the bell curve', 'Recall how much of a normal distribution falls within a given range.'),
  ('mission-ai-probability-sector-09-o2', 'mission-ai-probability-sector-09', 2, 'Judge an outlier', 'Judge how unusual an observation is under a normal distribution.'),

  ('mission-ai-probability-sector-10-o1', 'mission-ai-probability-sector-10', 1, 'Spot a biased sample', 'Find the evidence that reveals a sample was not chosen fairly.'),
  ('mission-ai-probability-sector-10-o2', 'mission-ai-probability-sector-10', 2, 'Know what more data fixes', 'Recognize that a larger biased sample is still biased.'),

  ('mission-ai-probability-sector-11-o1', 'mission-ai-probability-sector-11', 1, 'Tell correlation from causation', 'Find the evidence that actually rules out a causal explanation.'),

  ('mission-ai-probability-sector-12-o1', 'mission-ai-probability-sector-12', 1, 'Test against random chance', 'Judge whether Echo''s disagreement rate is higher than random chance alone would produce.'),
  ('mission-ai-probability-sector-12-o2', 'mission-ai-probability-sector-12', 2, 'Rule out a biased sample', 'Judge whether the result could simply be an artifact of how the data was sampled.'),
  ('mission-ai-probability-sector-12-o3', 'mission-ai-probability-sector-12', 3, 'Separate correlation from cause', 'Judge whether a correlated factor should be mistaken for the actual cause.'),
  ('mission-ai-probability-sector-12-o4', 'mission-ai-probability-sector-12', 4, 'State the verdict', 'Having tested the evidence three ways, state Cipher Division''s actual verdict on Echo''s behavior.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-ai-probability-sector-01-o1-c1', 'mission-ai-probability-sector-01-o1', 1, 'multiple_choice', 'Which of these is the best example of genuine randomness, rather than something that only looks unpredictable?', '{"question":"Which of these is the best example of genuine randomness, rather than something that only looks unpredictable?","options":[{"id":"a","text":"A coin flip, where each individual flip cannot be predicted but heads comes up close to half the time over many flips"},{"id":"b","text":"A calculator that gives a different answer to 2+2 depending on who is asking"},{"id":"c","text":"A clock that is simply running eight minutes slow"},{"id":"d","text":"A webpage that fails to load because a server is down"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),

  ('mission-ai-probability-sector-02-o1-c1', 'mission-ai-probability-sector-02-o1', 1, 'multiple_choice', 'A weighted die shows a 6 on about 1 out of every 3 rolls, on average, over many rolls. What is the probability of rolling a 6 on a single roll?', '{"question":"A weighted die shows a 6 on about 1 out of every 3 rolls, on average, over many rolls. What is the probability of rolling a 6 on a single roll?","options":[{"id":"a","text":"3"},{"id":"b","text":"1/3"},{"id":"c","text":"6"},{"id":"d","text":"It cannot be known, dice are unpredictable"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-probability-sector-03-o1-c1', 'mission-ai-probability-sector-03-o1', 1, 'multiple_choice', 'The general chance of rain today is 20%. The chance of rain today, given that the sky is currently overcast, is 70%. What does this tell us?', '{"question":"The general chance of rain today is 20%. The chance of rain today, given that the sky is currently overcast, is 70%. What does this tell us?","options":[{"id":"a","text":"Overcast skies cause rain 70% of the time, no matter what"},{"id":"b","text":"Knowing it is overcast changes the estimate of rain -- conditioning on new information updated the probability"},{"id":"c","text":"The two numbers are contradictory and one must be wrong"},{"id":"d","text":"Rain and overcast skies are unrelated"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-probability-sector-03-o2-c1', 'mission-ai-probability-sector-03-o2', 1, 'drag_and_drop', 'Sort each statement into plain probability or conditional probability.', '{"items":[{"id":"i1","text":"The chance a random Cipher Labs log line mentions Echo"},{"id":"i2","text":"The chance a log line mentions Echo, given it was logged during a power spike"},{"id":"i3","text":"The chance any single dice roll is a 6"},{"id":"i4","text":"The chance the next answer changes, given the previous two answers already changed"}],"targets":[{"id":"t1","label":"Plain probability"},{"id":"t2","label":"Conditional probability"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t1","i4":"t2"}}'::jsonb),

  ('mission-ai-probability-sector-04-o1-c1', 'mission-ai-probability-sector-04-o1', 1, 'multiple_choice', 'Which pair of events is the best example of independence?', '{"question":"Which pair of events is the best example of independence?","options":[{"id":"a","text":"Drawing a card, and drawing a second card from the same deck without replacing the first"},{"id":"b","text":"The result of a fair coin flip, and the result of a completely separate fair coin flip"},{"id":"c","text":"Today''s temperature, and tomorrow''s temperature"},{"id":"d","text":"A student''s study hours, and their exam score"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-probability-sector-04-o2-c1', 'mission-ai-probability-sector-04-o2', 1, 'investigation', 'A researcher claims a patient''s test result is independent of their age. Which evidence would actually refute that claim?', '{"evidence":[{"id":"e1","label":"Study data","detail":"Positive test rate is 4% for patients under 40 and 31% for patients over 65"},{"id":"e2","label":"Lab note","detail":"The test kits come from two different manufacturers"},{"id":"e3","label":"Clinic log","detail":"Tests are processed in the order patients arrive"}],"question":"Which evidence would actually refute the claim that test result is independent of age?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-probability-sector-05-o1-c1', 'mission-ai-probability-sector-05-o1', 1, 'interactive_diagram', 'Order the steps of a Bayesian belief update.', '{"diagramId":"bayesian-update","hotspots":[{"id":"prior","label":"Start with a prior belief","explanation":"Before seeing the new evidence, state how likely each explanation seemed."},{"id":"likelihood","label":"Ask how likely the evidence is under each explanation","explanation":"For each candidate explanation, ask how probable this exact evidence would be if that explanation were true."},{"id":"combine","label":"Combine the prior belief with the evidence","explanation":"Weigh each explanation by both how likely it was to begin with and how well it accounts for the evidence."},{"id":"posterior","label":"Arrive at an updated, posterior belief","explanation":"The result is a revised probability for each explanation, given the new evidence."}],"task":"Order the steps of a Bayesian update from first to last."}'::jsonb, '{"correctOrderIds":["prior","likelihood","combine","posterior"]}'::jsonb),
  ('mission-ai-probability-sector-05-o2-c1', 'mission-ai-probability-sector-05-o2', 1, 'multiple_choice', 'A rare condition affects 1 in 10,000 people. A test for it is 99% accurate. A random person tests positive. Which is the best intuition for why they are still probably unaffected?', '{"question":"A rare condition affects 1 in 10,000 people. A test for it is 99% accurate. A random person tests positive. Which is the best intuition for why they are still probably unaffected?","options":[{"id":"a","text":"The test is wrong 1% of the time, and 1% is small, so they are almost certainly affected"},{"id":"b","text":"Because the condition is so rare to begin with, a very low prior, even a small false-positive rate produces far more false positives than true positives among everyone who tests positive"},{"id":"c","text":"Bayes'' rule does not apply to medical tests"},{"id":"d","text":"A 99% accurate test can never be wrong"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-probability-sector-06-o1-c1', 'mission-ai-probability-sector-06-o1', 1, 'multiple_choice', 'Which of these is a valid random variable for describing Echo''s interaction logs?', '{"question":"Which of these is a valid random variable for describing Echo''s interaction logs?","options":[{"id":"a","text":"The literal text of Echo''s response"},{"id":"b","text":"The number of times Echo changed its answer to a repeated question in a given week"},{"id":"c","text":"The name of the engineer who filed the log"},{"id":"d","text":"The color used in the dashboard chart"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-probability-sector-06-o2-c1', 'mission-ai-probability-sector-06-o2', 1, 'drag_and_drop', 'Sort each random variable into discrete or continuous.', '{"items":[{"id":"i1","text":"Number of answer-changes logged in a day"},{"id":"i2","text":"Exact time, in seconds, between two identical questions"},{"id":"i3","text":"Number of questions asked in an hour"},{"id":"i4","text":"Temperature of the server room"}],"targets":[{"id":"t1","label":"Discrete"},{"id":"t2","label":"Continuous"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t1","i4":"t2"}}'::jsonb),

  ('mission-ai-probability-sector-07-o1-c1', 'mission-ai-probability-sector-07-o1', 1, 'multiple_choice', 'A random variable is 0 with probability 0.9, and 1 with probability 0.1. What is its expected value?', '{"question":"A random variable is 0 with probability 0.9, and 1 with probability 0.1. What is its expected value?","options":[{"id":"a","text":"0.5"},{"id":"b","text":"0.1"},{"id":"c","text":"0.9"},{"id":"d","text":"1.0"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-probability-sector-07-o2-c1', 'mission-ai-probability-sector-07-o2', 1, 'multiple_choice', 'Across many weeks, Echo''s logs show an expected value of 0.4 answer-changes per week. What does that actually mean?', '{"question":"Across many weeks, Echo''s logs show an expected value of 0.4 answer-changes per week. What does that actually mean?","options":[{"id":"a","text":"Every single week has exactly 0.4 changes"},{"id":"b","text":"The long-run average number of changes per week, across many weeks, settles near 0.4, even though any one week is always a whole number"},{"id":"c","text":"There is a 40% chance Echo is broken"},{"id":"d","text":"0.4 is the maximum possible number of changes in a week"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-probability-sector-08-o1-c1', 'mission-ai-probability-sector-08-o1', 1, 'multiple_choice', 'Process A and Process B both average 5 answer-changes per week. Process A is almost always between 4 and 6. Process B ranges anywhere from 0 to 15. Which has higher variance?', '{"question":"Process A and Process B both average 5 answer-changes per week. Process A is almost always between 4 and 6. Process B ranges anywhere from 0 to 15. Which has higher variance?","options":[{"id":"a","text":"Process A"},{"id":"b","text":"Process B"},{"id":"c","text":"They must be equal since the averages match"},{"id":"d","text":"Variance cannot be compared this way"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-probability-sector-08-o2-c1', 'mission-ai-probability-sector-08-o2', 1, 'multiple_choice', 'Two datasets have the exact same average. What does that tell you about their variance?', '{"question":"Two datasets have the exact same average. What does that tell you about their variance?","options":[{"id":"a","text":"Their variance must also be equal"},{"id":"b","text":"Nothing on its own -- variance is a separate measurement from the average, and can differ completely even when averages match"},{"id":"c","text":"The one with more data points automatically has lower variance"},{"id":"d","text":"Variance can be ignored once the average is known"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-probability-sector-09-o1-c1', 'mission-ai-probability-sector-09-o1', 1, 'multiple_choice', 'In a normal distribution, roughly what percentage of outcomes fall within two standard deviations of the average?', '{"question":"In a normal distribution, roughly what percentage of outcomes fall within two standard deviations of the average?","options":[{"id":"a","text":"50%"},{"id":"b","text":"68%"},{"id":"c","text":"95%"},{"id":"d","text":"100%"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),
  ('mission-ai-probability-sector-09-o2-c1', 'mission-ai-probability-sector-09-o2', 1, 'multiple_choice', 'A process is normally distributed. An observed value sits four standard deviations from the average. What is the best description of that observation?', '{"question":"A process is normally distributed. An observed value sits four standard deviations from the average. What is the best description of that observation?","options":[{"id":"a","text":"Perfectly typical, nothing to look at"},{"id":"b","text":"Extremely unusual under this distribution -- something that far out happens by chance only a tiny fraction of the time"},{"id":"c","text":"Proof the distribution itself is wrong"},{"id":"d","text":"Impossible, and therefore must be a data entry error"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-probability-sector-10-o1-c1', 'mission-ai-probability-sector-10-o1', 1, 'investigation', 'Which evidence points to a sample that is actually biased and untrustworthy?', '{"evidence":[{"id":"e1","label":"Sampling method","detail":"Analysts pulled the first 5,000 log entries chronologically, all from a single week when Echo was in a known low-activity state"},{"id":"e2","label":"Sampling method, alternate","detail":"Analysts pulled 5,000 log entries at random, spread evenly across the entire year of logs"},{"id":"e3","label":"Sample size note","detail":"Both samples are the same size, 5,000 entries"}],"question":"Which evidence points to a sample that is actually biased and untrustworthy?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-probability-sector-10-o2-c1', 'mission-ai-probability-sector-10-o2', 1, 'multiple_choice', 'A biased sample is made ten times larger, but still pulled the same biased way. What happens to the bias?', '{"question":"A biased sample is made ten times larger, but still pulled the same biased way. What happens to the bias?","options":[{"id":"a","text":"It disappears once the sample is large enough"},{"id":"b","text":"It does not go away -- a larger biased sample is still biased, just with more confident-looking wrong conclusions"},{"id":"c","text":"Bias only affects small samples"},{"id":"d","text":"Sample size and bias are the same thing"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-probability-sector-11-o1-c1', 'mission-ai-probability-sector-11-o1', 1, 'investigation', 'Which evidence shows that the power-draw and answer-change correlation is not actually causal?', '{"evidence":[{"id":"e1","label":"Correlation observed","detail":"Weeks with higher Cipher Labs power draw also show more Echo answer-changes"},{"id":"e2","label":"Controlled test","detail":"Engineers throttled power draw directly and Echo''s answer-change rate did not budge"},{"id":"e3","label":"Speculation","detail":"A junior analyst assumes higher power draw must be causing Echo to change its answers, since the two rise together"}],"question":"Which evidence shows that the power-draw and answer-change correlation is not actually causal?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-ai-probability-sector-12-o1-c1', 'mission-ai-probability-sector-12-o1', 1, 'investigation', 'Which evidence together shows the disagreement rate is far higher than random chance alone would produce?', '{"evidence":[{"id":"e1","label":"Random-noise baseline","detail":"If answer-changes were pure random noise with no underlying cause, repeat-question tests would be expected to disagree roughly 3% of the time by chance alone"},{"id":"e2","label":"Observed rate","detail":"Across a full year of paired repeat-questions, Echo''s answers actually disagreed 22% of the time"},{"id":"e3","label":"Sample size","detail":"The comparison covers 1,400 paired repeat-questions, sampled at random across the full year, not clustered in any single week"}],"question":"Which evidence together shows the disagreement rate is far higher than random chance alone would produce?"}'::jsonb, '{"requiredEvidenceIds":["e1","e2"]}'::jsonb),
  ('mission-ai-probability-sector-12-o2-c1', 'mission-ai-probability-sector-12-o2', 1, 'investigation', 'Which evidence rules out the possibility that this result is just an artifact of a biased or unlucky sample?', '{"evidence":[{"id":"e1","label":"Sampling method","detail":"The 1,400 paired-question comparisons were pulled at random across the entire year, not concentrated in any single week, shift or condition"},{"id":"e2","label":"Alternate explanation","detail":"A skeptic suggests the sample might have been cherry-picked from an unusually active week"},{"id":"e3","label":"Verification","detail":"Byte re-ran the sampling procedure with a different random seed and got a disagreement rate of 21%, consistent with the original 22%"}],"question":"Which evidence rules out the possibility that this result is just an artifact of a biased or unlucky sample?"}'::jsonb, '{"requiredEvidenceIds":["e1","e3"]}'::jsonb),
  ('mission-ai-probability-sector-12-o3-c1', 'mission-ai-probability-sector-12-o3', 1, 'investigation', 'Which evidence should stop Cipher Division from concluding that power draw is causing the answer-changes?', '{"evidence":[{"id":"e1","label":"Correlation","detail":"Weeks with more repeat-question disagreements also tend to be weeks with higher Cipher Labs power draw"},{"id":"e2","label":"Controlled check","detail":"Power draw was throttled directly in a controlled test, and the disagreement rate did not change"},{"id":"e3","label":"Speculation","detail":"One theory holds that power draw itself is driving Echo to change its answers"}],"question":"Which evidence should stop Cipher Division from concluding that power draw is causing the answer-changes?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),
  ('mission-ai-probability-sector-12-o4-c1', 'mission-ai-probability-sector-12-o4', 1, 'boss_encounter', 'Having tested the evidence against random chance, against sampling bias, and against a false cause, state Cipher Division''s actual verdict.', '{"stages":[{"objectiveRef":"mission-ai-probability-sector-12-o1","label":"Test against random chance"},{"objectiveRef":"mission-ai-probability-sector-12-o2","label":"Rule out a biased sample"},{"objectiveRef":"mission-ai-probability-sector-12-o3","label":"Separate correlation from cause"}],"task":"State the verdict in one sentence: is Echo''s answer-changing behavior statistical noise, or a real, non-random signal, and what should Cipher Division investigate next."}'::jsonb, '{"requiredObjectiveIds":["mission-ai-probability-sector-12-o1","mission-ai-probability-sector-12-o2","mission-ai-probability-sector-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-ai-probability-sector-01-o1-c1', 'orientation', 'Ask which option would still show a stable, describable pattern if you repeated it thousands of times.', 10, 1),
  ('mission-ai-probability-sector-01-o1-c1', 'concept', 'A broken calculator, a slow clock and a down server are not random -- they are simply wrong, or malfunctioning, in a fixed way.', 20, 2),
  ('mission-ai-probability-sector-01-o1-c1', 'solution', 'The coin flip is genuine randomness: no single flip is predictable, but the long-run frequency of heads is stable near 50%. That combination of per-trial unpredictability and long-run stability is the actual definition.', 30, 3),

  ('mission-ai-probability-sector-02-o1-c1', 'orientation', 'Probability is always a number between 0 and 1, or written as a fraction or percentage.', 10, 1),
  ('mission-ai-probability-sector-02-o1-c1', 'concept', '1 out of every 3 rolls translates directly into a fraction.', 20, 2),
  ('mission-ai-probability-sector-02-o1-c1', 'solution', '1/3, about 0.33, is the probability -- it is the long-run relative frequency, not a raw count.', 30, 3),

  ('mission-ai-probability-sector-03-o1-c1', 'orientation', 'Conditional probability describes an updated belief given new information, not necessarily cause and effect.', 10, 1),
  ('mission-ai-probability-sector-03-o1-c1', 'solution', '70% is not the general chance of rain -- it is the chance of rain in the narrower situation where the sky is already known to be overcast. Option b.', 20, 2),
  ('mission-ai-probability-sector-03-o2-c1', 'orientation', 'Look for the word given, or an equivalent narrowing condition, in each statement.', 10, 1),
  ('mission-ai-probability-sector-03-o2-c1', 'solution', 'Plain probability: a random log line mentioning Echo, any single dice roll being a 6. Conditional probability: a log line during a power spike, an answer changing given the previous two already changed.', 20, 2),

  ('mission-ai-probability-sector-04-o1-c1', 'orientation', 'Ask whether the outcome of the first event changes the odds of the second at all.', 10, 1),
  ('mission-ai-probability-sector-04-o1-c1', 'solution', 'Two separate fair coin flips do not affect each other. The other three examples all shift each other''s odds. Option b.', 20, 2),
  ('mission-ai-probability-sector-04-o2-c1', 'orientation', 'True independence would mean the rate stays the same across every group.', 10, 1),
  ('mission-ai-probability-sector-04-o2-c1', 'solution', 'e1: the positive rate is wildly different by age group, so age and test result are not independent.', 20, 2),

  ('mission-ai-probability-sector-05-o1-c1', 'orientation', 'Nothing can be combined before you know both the starting belief and how well the evidence fits each explanation.', 10, 1),
  ('mission-ai-probability-sector-05-o1-c1', 'solution', 'Prior, then likelihood, then combine, then posterior.', 20, 2),
  ('mission-ai-probability-sector-05-o2-c1', 'orientation', 'Think about how many unaffected people there are compared to affected people, not just the test''s accuracy rate alone.', 10, 1),
  ('mission-ai-probability-sector-05-o2-c1', 'concept', 'Out of 10,000 people, about 1 is truly affected, and roughly 100 unaffected people will still test positive by mistake, 1% of the remaining 9,999.', 20, 2),
  ('mission-ai-probability-sector-05-o2-c1', 'solution', 'Option b -- the rarity of the condition, the low prior, dominates the result. Most positives come from the huge pool of unaffected people, not the tiny pool of affected ones.', 30, 3),

  ('mission-ai-probability-sector-06-o1-c1', 'orientation', 'A random variable has to be a number produced by the random process.', 10, 1),
  ('mission-ai-probability-sector-06-o1-c1', 'solution', 'Option b -- it is the only option that is a number generated by the process itself.', 20, 2),
  ('mission-ai-probability-sector-06-o2-c1', 'orientation', 'Discrete values can be counted one by one. Continuous values can fall anywhere on a scale.', 10, 1),
  ('mission-ai-probability-sector-06-o2-c1', 'solution', 'Discrete: number of answer-changes in a day, number of questions in an hour. Continuous: exact time between questions, server room temperature.', 20, 2),

  ('mission-ai-probability-sector-07-o1-c1', 'orientation', 'Multiply each outcome by its own probability, then add the results.', 10, 1),
  ('mission-ai-probability-sector-07-o1-c1', 'solution', '0 times 0.9, plus 1 times 0.1, equals 0.1.', 20, 2),
  ('mission-ai-probability-sector-07-o2-c1', 'orientation', 'An expected value almost never has to match any single real outcome.', 10, 1),
  ('mission-ai-probability-sector-07-o2-c1', 'solution', 'Option b -- expectation is a long-run average, not a per-week guarantee and not a probability of failure.', 20, 2),

  ('mission-ai-probability-sector-08-o1-c1', 'orientation', 'Variance measures spread, not the average itself.', 10, 1),
  ('mission-ai-probability-sector-08-o1-c1', 'solution', 'Process B swings much further from its average, so it has higher variance even though the averages match. Option b.', 20, 2),
  ('mission-ai-probability-sector-08-o2-c1', 'orientation', 'The average is a single summary number. Spread is a completely separate question.', 10, 1),
  ('mission-ai-probability-sector-08-o2-c1', 'solution', 'Option b -- average and variance are independent measurements. Matching averages say nothing about matching spread.', 20, 2),

  ('mission-ai-probability-sector-09-o1-c1', 'orientation', 'Recall the 68, 95, 99.7 rule for one, two and three standard deviations.', 10, 1),
  ('mission-ai-probability-sector-09-o1-c1', 'solution', 'Option c -- about 95% of outcomes fall within two standard deviations of the average.', 20, 2),
  ('mission-ai-probability-sector-09-o2-c1', 'orientation', 'Four standard deviations out is much further than the 99.7% range covered by three.', 10, 1),
  ('mission-ai-probability-sector-09-o2-c1', 'solution', 'Option b -- an observation that far out is genuinely rare under the distribution, not impossible, but worth taking seriously.', 20, 2),

  ('mission-ai-probability-sector-10-o1-c1', 'orientation', 'A fair sample should not be limited to one narrow slice of time or condition.', 10, 1),
  ('mission-ai-probability-sector-10-o1-c1', 'solution', 'e1: pulling only one low-activity week, all from one point in time, cannot represent a full year of behavior.', 20, 2),
  ('mission-ai-probability-sector-10-o2-c1', 'orientation', 'Ask whether the sampling method itself, not just its size, was ever fixed.', 10, 1),
  ('mission-ai-probability-sector-10-o2-c1', 'solution', 'Option b -- more of a biased sample just produces more confidently wrong conclusions, since the underlying selection problem never changed.', 20, 2),

  ('mission-ai-probability-sector-11-o1-c1', 'orientation', 'A real causal claim should survive a direct test, not just a shared trend.', 10, 1),
  ('mission-ai-probability-sector-11-o1-c1', 'concept', 'e1 only shows the two moving together, and e3 is exactly the mistake Maya is warning about.', 20, 2),
  ('mission-ai-probability-sector-11-o1-c1', 'solution', 'e2 -- directly changing power draw and seeing no effect on the answer-change rate is what actually rules out causation, despite the correlation in e1.', 30, 3),

  ('mission-ai-probability-sector-12-o1-c1', 'orientation', 'Compare the observed rate directly against what pure random noise would produce.', 10, 1),
  ('mission-ai-probability-sector-12-o1-c1', 'solution', 'e1 sets the random-chance baseline near 3%. e2 shows the actual rate is 22%, far above that baseline -- together they show this is not what noise alone would produce.', 20, 2),
  ('mission-ai-probability-sector-12-o2-c1', 'orientation', 'A trustworthy sample is drawn without bias, and a trustworthy result reproduces when it is checked again.', 10, 1),
  ('mission-ai-probability-sector-12-o2-c1', 'solution', 'e1 shows the sampling itself was unbiased, spread across the full year. e3 shows a second, independent draw reproduced almost the same rate -- together they rule out an unlucky or cherry-picked sample.', 20, 2),
  ('mission-ai-probability-sector-12-o3-c1', 'orientation', 'A correlation on its own is never enough to prove which side is the cause.', 10, 1),
  ('mission-ai-probability-sector-12-o3-c1', 'solution', 'e2 -- throttling power draw directly and seeing no change in the disagreement rate is what rules out power draw as the cause, despite the correlation in e1.', 20, 2),
  ('mission-ai-probability-sector-12-o4-c1', 'orientation', 'Look at what all three tests had in common as a method, not at their individual answers.', 15, 1),
  ('mission-ai-probability-sector-12-o4-c1', 'solution', 'The math holds up: Echo''s behavior is not statistical noise. It clears the random-chance baseline, it survives a check for sampling bias, and the nearest correlated factor fails a direct causal test. Something about Echo really is changing, consistently, in a way random chance essentially rules out -- which means the next question is not whether, it is what data could possibly be causing it, and whether Cipher Division can find that data before Echo finishes whatever it is doing with it.', 25, 2);
